/* Daily work, evidence-based project brief, structured communication capture. */
(function(){
const prev={render,other,detail,action,modal};
let workTab='action',scope='today';
const states={action:'待我处理',customer:'等待客户',internal:'等待内部',done:'已完成'};
const nextDate=(days=1)=>{let d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+days);return localDate(d)};
const state=t=>t.done?'done':(['action','customer','internal'].includes(t.state)?t.state:'action');
const activeTasks=()=>data.tasks.filter(t=>!getp(t.pid)?.archived);
const log=(action,pid,detail)=>{data.audit.push({id:id(),at:new Date().toISOString(),action,pid,detail})};
function relevant(){let ts=activeTasks().filter(t=>state(t)===workTab);if(scope==='today'&&workTab==='action')ts=ts.filter(t=>!t.date||t.date<=today());return [...ts].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'))}
function dateLabel(t){if(!t.date)return '未定日期';if(state(t)==='done')return '完成于 '+(t.completedAt?.slice(0,10)||t.date);if(t.date<today())return '已逾期 · '+t.date;if(t.date===today())return (['customer','internal'].includes(state(t))?'预计今天反馈':'今天');return '预计 '+t.date}
function taskForm(task=null){const ps=data.projects.filter(p=>!p.archived),initial=task?.pid||selected||'',opts=[['','不关联项目'],...ps.map(p=>[p.id,p.name])];if(task?.pid&&!ps.some(p=>p.id===task.pid)&&getp(task.pid))opts.push([task.pid,getp(task.pid).name]);opts.sort(([a],[b])=>a===initial?-1:b===initial?1:0);modal(task?'调整待办':'新增待办',field('待办内容 *','title','text',task?.title||'',true)+select('关联项目（可选）','pid',opts)+field('截止日期','date','date',task?.date||today())+select('处理状态','state',Object.entries(states).filter(([k])=>k!=='done').sort(([a],[b])=>task?(a===state(task)?-1:b===state(task)?1:0):0)),v=>{v.title=v.title.trim();if(!v.title)throw Error('请填写待办内容');if(v.pid&&!getp(v.pid))throw Error('关联项目不存在');if(!['action','customer','internal'].includes(v.state))throw Error('请选择处理状态');if(!v.date)throw Error('请设置截止日期');if(task){const t=data.tasks.find(t=>t.id===task.id);Object.assign(t,v,{done:false});log('调整待办',v.pid,v.title)}else{data.tasks.push({...v,id:id(),done:false,owner:getp(v.pid)?.owner||'我',createdDate:today()});log('新增待办',v.pid,v.title)}},{drawer:true})}
function finishTask(t){const p=getp(t.pid);modal('完成待办',`<div class="field full"><b>${esc(t.title)}</b><p class="muted small">${esc(p?.name||'个人待办')}</p></div>`+area('完成结果 *','result')+(p?select('同步记录项目进展','updateProgress',[['no','仅完成待办'],['yes','同时写入项目进展时间线']]):''),v=>{if(!v.result.trim())throw Error('请简单记录完成结果');const target=data.tasks.find(x=>x.id===t.id),at=new Date().toISOString();Object.assign(target,{done:true,state:'done',result:v.result.trim(),completedAt:at});if(p&&v.updateProgress==='yes'){p.events.push({id:id(),date:today(),time:recordClock(),recordedAt:at,type:YunchengV3.stageAt(p,today()),title:'完成待办：'+t.title,body:v.result.trim(),source:'待办完成',taskId:t.id});log('更新项目进展',p.id,t.title)}log('完成待办',t.pid,t.title+'：'+v.result.trim())},{drawer:true})}
function postpone(t){modal('调整跟进日期',`<div class="field full"><b>${esc(t.title)}</b></div>`+field('新的跟进日期','date','date',nextDate())+field('调整原因 *','reason','text','',true),v=>{if(!v.date||!v.reason.trim())throw Error('请填写日期和调整原因');const target=data.tasks.find(x=>x.id===t.id);target.date=v.date;target.history??=[];target.history.push({at:new Date().toISOString(),date:v.date,reason:v.reason});log('调整跟进日期',t.pid,v.reason)},{drawer:true})}
function workPage(){const ts=activeTasks(),counts=Object.fromEntries(Object.keys(states).map(k=>[k,ts.filter(t=>state(t)===k).length])),due=ts.filter(t=>state(t)==='action'&&t.date<=today()).length,waiting=counts.customer+counts.internal,items=relevant();const allProjects=data.projects.filter(p=>!p.archived),stale=allProjects.filter(p=>(new Date(today())-new Date(latest(p)?.date||created(p)))/86400000>=14);return `<section class="daily"><div class="daily-hero"><div><h1>今日工作</h1><p>${new Date(today()+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})} · ${due} 项需要处理，${waiting} 项等待反馈</p></div><button class="primary" data-v6="newtask">＋ 新增待办</button></div><div class="daily-counts"><button data-work="action"><span class="count-mark blue-mark">↗</span><div><b>${due}</b><span>到期待办</span></div></button><button data-work="customer"><span class="count-mark violet-mark">◷</span><div><b>${counts.customer}</b><span>等待客户</span></div></button><button data-work="internal"><span class="count-mark amber-mark">↔</span><div><b>${counts.internal}</b><span>等待内部</span></div></button><button data-work="done"><span class="count-mark green-mark">✓</span><div><b>${counts.done}</b><span>已经完成</span></div></button></div><div class="daily-grid"><section class="panel daily-list"><div class="daily-list-head"><div class="daily-tabs">${Object.entries(states).map(([key,label])=>`<button data-work="${key}" class="${workTab===key?'active':''}">${label}<small>${counts[key]}</small></button>`).join('')}</div></div><div class="daily-list-filters"><span>${workTab==='action'?'明确行动、时间和负责人。':workTab==='done'?'完成结果保留在待办记录中。':'已经做了，正在等待对方的反馈。'}</span>${workTab==='action'?`<div class="seg"><button data-scope="today" class="${scope==='today'?'on':''}">今天及逾期</button><button data-scope="all" class="${scope==='all'?'on':''}">全部</button></div>`:''}</div>${items.map(t=>`<article class="daily-task"><div class="daily-task-main"><span class="daily-status ${state(t)}">${state(t)==='done'?'✓':state(t)==='action'?'○':'◷'}</span><div class="daily-task-copy"><h3>${esc(t.title)}</h3>${getp(t.pid)?`<button class="task-project" data-v6-project="${t.pid}">${esc(getp(t.pid).name)} ↗</button>`:`<span class="muted small">个人待办</span>`}<p>${['customer','internal'].includes(state(t))?'等待 '+esc(t.contact||(state(t)==='customer'?'客户反馈':'内部反馈')):'负责人 '+esc(t.owner||'我')}<span>·</span><time class="${!t.done&&t.date<today()?'overdue':''}">${dateLabel(t)}</time></p>${t.note?`<div class="daily-task-note">${esc(t.note)}</div>`:''}${t.result?`<div class="daily-task-result">结果：${esc(t.result)}</div>`:''}</div></div><div class="daily-task-actions">${state(t)==='done'?`<button data-task6="reopen" data-id="${t.id}">重新打开</button>`:state(t)==='action'?`<button class="primary quiet" data-task6="finish" data-id="${t.id}">完成</button><button data-task6="adjust" data-id="${t.id}">调整</button>`:`<button class="primary quiet" data-task6="feedback" data-id="${t.id}">记反馈</button><button data-task6="postpone" data-id="${t.id}">改日期</button><button data-task6="adjust" data-id="${t.id}">调整</button>`}</div></article>`).join('')||`<div class="daily-empty"><span>${workTab==='done'?'✓':'◷'}</span><h3>${workTab==='action'?'今天暂无到期待办':workTab==='done'?'还没有完成记录':'暂无等待事项'}</h3><p>${workTab==='action'?'查看后续安排，或添加一项待办。':'新增待办后，可在这里跟踪处理状态。'}</p><button class="link" data-v6="alltasks">查看全部待办 →</button></div>`}</section></div></section>`}
function recentEvent(p){return [...(p.events||[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.recordedAt||'').localeCompare(a.recordedAt||''))[0]}
function briefData(p){const b=p.brief||{},e=recentEvent(p),t=data.tasks.filter(t=>t.pid===p.id&&!t.done).sort((a,b)=>a.date.localeCompare(b.date))[0];return {need:b.need||p.background||'未填写',position:b.position||e?.title||'暂无进展',blocker:b.blocker||'未填写',next:b.next||t?.title||'未安排',people:b.people||[p.owner?'项目负责人：'+p.owner:'',t?.contact?'跟进接口人：'+t.contact:''].filter(Boolean).join('；')||'未填写',manual:!!p.brief,stale:!!p.brief&&!!e&&e.recordedAt>p.brief.confirmedAt,sourceDate:e?.date||null,task:t}}
function briefCard(p){const b=briefData(p);return `<section class="panel project-brief"><div class="brief-head"><div><h2>项目摘要</h2></div><div><button class="link" data-v6="brief-copy">复制摘要</button><button class="brief-edit" data-v6="brief-edit">编辑确认</button></div></div><div class="brief-grid"><div class="brief-need"><span>客户需求</span><p>${esc(b.need)}</p></div><div><span>当前进展</span><p>${esc(b.position)}</p></div><div><span>主要阻碍</span><p>${esc(b.blocker)}</p></div><div><span>下一步行动</span><p>${esc(b.next)}</p></div><div><span>相关人员</span><p>${esc(b.people)}</p></div></div><div class="brief-source"><span>${b.manual?'手工维护 · '+(p.brief.confirmedAt?.slice(0,10)||'')+(b.stale?' · 有新进展，建议复核':''):'来源：项目背景、进展与待办'}</span><button class="link" data-v6="brief-sources">查看依据 →</button></div></section>`}
function editBrief(){const p=getp(selected),b=briefData(p);modal('编辑项目摘要',`<div class="field full brief-form-note">根据项目事实填写，确认后保存为手工摘要，不自动覆盖后续进展。</div>`+[['客户需求','need'],['当前进展','position'],['主要阻碍','blocker'],['下一步行动','next'],['相关人员','people']].map(([label,key])=>`<label class="field full">${label}<textarea name="${key}">${esc(b[key])}</textarea></label>`).join(''),v=>{const p=getp(selected);p.brief={...v,confirmedAt:new Date().toISOString()};log('确认项目摘要',p.id,'手工确认需求、进展、阻碍与下一步')},{drawer:true})}
function capture(channel='电话沟通',pid=selected,fromTask=null){const ps=data.projects.filter(p=>!p.archived);if(!ps.length)return toast('请先登记一个项目');const initial=pid&&ps.some(p=>p.id===pid)?pid:ps[0].id;const opts=[[initial,getp(initial).name],...ps.filter(p=>p.id!==initial).map(p=>[p.id,p.name])];const progressOptions=['需求调研','方案交流','报价商务','招投标','已签约','交付实施','运维服务','暂停'];const current=progressOptions.includes(getp(initial).stage)?getp(initial).stage:'需求调研';modal(fromTask?'记录反馈与下一步':'进展更新',select('关联项目','pid',opts)+select('项目进展','progressStage',[current,...progressOptions.filter(s=>s!==current)])+field('进展日期','date','date',today())+field('进展时间','time','time',recordClock())+field('相关人员（可选）','participants','text',fromTask?.contact||'')+field('进展标题 *','title','text',fromTask?'反馈：'+fromTask.title:'',true)+area('进展说明 *','conclusion')+`<p class="field full muted small">保存后同步更新项目阶段。签约金额请在“金额报价”中登记合同，阶段选择不会生成金额记录。</p>`+field('下一步行动','next','text','',true)+select('下一步状态','nextState',[['action','待我处理'],['customer','等待客户'],['internal','等待内部']])+field('截止 / 预计反馈日期','due','date',nextDate()),v=>{const p=getp(v.pid);if(!v.date||v.date<created(p)||v.date>today())throw Error('发生日期须在项目登记日期与今天之间');if(!progressOptions.includes(v.progressStage))throw Error('请选择项目进展');if(!v.conclusion.trim())throw Error('请填写进展说明');if(fromTask&&v.pid!==fromTask.pid)throw Error('反馈须关联原等待事项的项目');if(v.next.trim()&&(!v.due||v.due<v.date))throw Error('下一步日期不能早于本次进展日期');const body=v.conclusion.trim();const event={id:id(),date:v.date,time:v.time,type:v.progressStage,title:v.title,body,key:v.key==='yes',source:v.source,recordedAt:new Date().toISOString(),communication:{participants:v.participants,conclusion:v.conclusion},feedbackFor:fromTask?.id||null};p.events.push(event);if(YunchengV3.stageAt(p,v.date)!==v.progressStage){p.stageHistory.push({id:id(),date:v.date,stage:v.progressStage,recordedAt:event.recordedAt,source:v.title,eventId:event.id});}p.stage=YunchengV3.stageAt(p,today());if(fromTask){const t=data.tasks.find(t=>t.id===fromTask.id);Object.assign(t,{done:true,state:'done',completedAt:new Date().toISOString(),result:v.conclusion,feedbackEvent:event.id})}if(v.next.trim())data.tasks.push({id:id(),pid:p.id,title:v.next,date:v.due,state:v.nextState,done:false,contact:fromTask?.contact||'',owner:fromTask?.owner||p.owner||'我',sourceEvent:event.id,createdDate:today()});log(fromTask?'收到反馈':'更新项目进展',p.id,v.title);if(selected===p.id)tab='进展时间线';else{page='待办与风险';workTab=v.next.trim()?v.nextState:'action'}},{drawer:true});const projectSelect=document.querySelector('.dialog [name=pid]'),stageSelect=document.querySelector('.dialog [name=progressStage]');projectSelect.onchange=()=>{const stage=getp(projectSelect.value)?.stage;stageSelect.value=progressOptions.includes(stage)?stage:'需求调研';stageSelect.dispatchEvent(new Event('input',{bubbles:true}));};}
other=function(){if(page==='待办与风险')return workPage();return prev.other()};
detail=function(){const h=prev.detail();if(tab!=='概览')return h;return h.replace('<div class="detailgrid">',briefCard(getp(selected))+'<div class="detailgrid">')};
action=function(a){if(a==='task')return taskForm();if(a==='progress')return capture('电话沟通',selected);return prev.action(a)};
function decorate(){
 document.querySelectorAll('[data-nav="待办与风险"],[data-v4-nav="待办与风险"]').forEach(el=>{el.setAttribute('aria-label','今日工作');const text=el.querySelector('.label')||el.querySelector('span');if(text)text.textContent='今日工作'});
 if(page==='待办与风险'&&!selected){document.querySelector('.content>.heading')?.remove();const crumb=document.querySelector('.crumb span');if(crumb)crumb.textContent='/　今日工作';}
 if(selected){const btn=document.querySelector('[data-action="progress"]');if(btn)btn.textContent='＋ 进展更新';}
 document.querySelectorAll('[data-work]').forEach(el=>el.onclick=()=>{workTab=el.dataset.work;render()});document.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>{scope=el.dataset.scope;render()});
 document.querySelectorAll('[data-v6-project]').forEach(el=>el.onclick=()=>openp(el.dataset.v6Project));document.querySelectorAll('[data-channel]').forEach(el=>el.onclick=()=>capture(el.dataset.channel,null));
 document.querySelectorAll('[data-task6]').forEach(el=>el.onclick=()=>{const t=data.tasks.find(t=>t.id===el.dataset.id);if(el.dataset.task6==='finish')finishTask(t);if(el.dataset.task6==='adjust')taskForm(t);if(el.dataset.task6==='postpone')postpone(t);if(el.dataset.task6==='feedback'){if(t.pid)capture('电话沟通',t.pid,t);else finishTask(t);}if(el.dataset.task6==='reopen')modal('重新打开行动',`<div class="field full"><p>${esc(t.title)}</p></div>`,()=>{const current=data.tasks.find(x=>x.id===t.id);current.done=false;current.state='action';log('重新打开行动',t.pid,t.title)},{drawer:true})});
 document.querySelectorAll('[data-v6]').forEach(el=>el.onclick=async()=>{const a=el.dataset.v6;if(a==='capture')capture('电话沟通',selected);if(a==='newtask')taskForm();if(a==='alltasks'){scope='all';workTab='action';render()}if(a==='stale')action('stale');if(a==='brief-edit')editBrief();if(a==='brief-sources'){const p=getp(selected),b=briefData(p),e=recentEvent(p);modal('摘要依据',`<div class="field full"><h3>项目背景</h3><p>${esc(p.background||'未填写')}</p><h3>最近进展 ${e?.date||''}</h3><p>${esc(e?.title||'尚未记录')}</p><p>${esc(e?.body||'')}</p><h3>下一步待办</h3><p>${esc(b.task?.title||'尚未安排')}</p><h3>手工摘要</h3><p>${p.brief?'已手工维护，内容不会被后续记录自动覆盖。':'尚未手工维护。当前展示的是记录汇总，不是AI推断。'}</p></div>`,()=>{},{readonly:true,drawer:true})}if(a==='brief-copy'){const p=getp(selected),b=briefData(p),text=p.name+'\n客户：'+p.unit+'\n\n客户需求：'+b.need+'\n当前进展：'+b.position+'\n主要阻碍：'+b.blocker+'\n下一步行动：'+b.next+'\n相关人员：'+b.people;try{await navigator.clipboard.writeText(text);toast('项目摘要已复制')}catch{download(text,'text/plain;charset=utf-8',p.name+'-项目摘要.txt');toast('已下载摘要文本')}}});
}
render=function(){prev.render();decorate()};
if(new URLSearchParams(location.search).get('view')==='today')page='待办与风险';
window.YunchengDaily={taskState:state,briefData};
})();
